<!doctype html><html><body style="font-family:Arial,sans-serif;line-height:1.6;color:#12213a"><h2>New Public Complaint</h2><p><b>Reference:</b> {{ $complaint->reference_no }}</p><p><b>Name:</b> {{ $complaint->full_name }}</p><p><b>Mobile:</b> {{ $complaint->mobile }}</p><p><b>Email:</b> {{ $complaint->email ?: 'Not provided' }}</p><p><b>Address:</b><br>{{ $complaint->address }}</p><p><b>State / District:</b> {{ $complaint->state }} / {{ $complaint->district }}</p><p><b>Subject:</b> {{ $complaint->subject }}</p><p><b>Complaint:</b><br>{{ $complaint->details }}</p><p><b>Submitted:</b> {{ $complaint->created_at }}</p></body></html>
